const data = $input.first().json;
const messages = data.messages || [{ text: data.main_message, parse_mode: 'Markdown' }];

return messages.map(msg => ({
  json: {
    chat_id: data.chat_id,
    text: msg.text,
    parse_mode: msg.parse_mode || 'Markdown'
  }
}));
